B.b6c=new A.bn(9,"odjede","sfx_story_truck_leave",null,1)
B.b6z=new A.bn(9,"tik\xe1n\xed","sfx_story_soft_ticking",null,1)
B.a7M=s([B.b6w,B.b6i,B.b6c,B.b6z],t.c)
B.aHI=new A.h(0,0,170.20355132091814,311.82330012992634)
B.aIf=new A.h(120,0,311.85794716327416,170.20355132091814)
B.aFv=new A.h(129.9,129.9,311.79692507579034,311.79692507579034)
B.iY=s([B.aHI,B.aIf,B.aFv],t.u)
B.ahc=new A.b2("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.c6=new A.lT("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.a2v=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.aUp=new A.a8(B.c6,B.a2v,!1)
B.be=new A.lT("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.a5T=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.aWl=new A.a8(B.be,B.a5T,!1)
B.aa5=s([B.ahc,B.aUp,B.aWl],t.a)
B.aXl=new A.cy("story_00_intro",B.aa5)
B.agG=new A.b2("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.a3c=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.aUx=new A.a8(B.c6,B.a3c,!1)
B.ahj=new A.b2("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.a3l=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.aUt=new A.a8(B.be,B.a3l,!1)
B.cc=new A.lT("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.ab3=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.aWa=new A.a8(B.cc,B.ab3,!1)
B.a3y=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.aVC=new A.a8(B.c6,B.a3y,!1)
B.aaf=s([B.agG,B.aUx,B.ahj,B.aUt,B.aWa,B.aVC],t.a)
B.aX3=new A.cy("story_01a_clubhouse_arrival",B.aaf)
B.a4D=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.aV1=new A.a8(B.c6,B.a4D,!1)
B.a6d=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.aVG=new A.a8(B.cc,B.a6d,!1)
B.a1A=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.aVY=new A.a8(B.be,B.a1A,!1)
B.a3h=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.aVV=new A.a8(B.cc,B.a3h,!1)
B.a2x=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.aVe=new A.a8(B.be,B.a2x,!1)
B.a0y=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.aUc=new A.a8(B.c6,B.a0y,!1)
B.a8l=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.aWp=new A.a8(B.be,B.a8l,!1)
B.ace=s([B.aV1,B.aVG,B.aVY,B.aVV,B.aVe,B.aUc,B.aWp],t.a)
B.aWZ=new A.cy("story_01b_legend_and_time",B.ace)
B.ahK=new A.b2("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.a4H=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.aV8=new A.a8(B.be,B.a4H,!1)
B.a45=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.aWy=new A.a8(B.cc,B.a45,!1)
B.abJ=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.aVU=new A.a8(B.be,B.abJ,!1)
B.a7Y=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.aU7=new A.a8(B.cc,B.a7Y,!1)
B.a2j=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.aUa=new A.a8(B.c6,B.a2j,!1)
B.a6I=s([B.ahK,B.aV8,B.aWy,B.aVU,B.aU7,B.aUa],t.a)
B.aWY=new A.cy("story_02_torn_map",B.a6I)
B.a1B=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.aV7=new A.a8(B.c6,B.a1B,!1)
B.a8M=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.aWf=new A.a8(B.be,B.a8M,!1)
B.ah_=new A.b2("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.ab7=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.aWg=new A.a8(B.cc,B.ab7,!1)
B.abm=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.aWj=new A.a8(B.be,B.abm,!1)
B.a7v=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.aUv=new A.a8(B.c6,B.a7v,!1)
B.a1X=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.aV_=new A.a8(B.be,B.a1X,!1)
B.a21=s([B.aV7,B.aWf,B.ah_,B.aWg,B.aWj,B.aUv,B.aV_],t.a)
B.aX_=new A.cy("story_03_founders_trail",B.a21)
B.agI=new A.b2("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.a3K=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.aWt=new A.a8(B.be,B.a3K,!1)
B.a8g=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.aVP=new A.a8(B.cc,B.a8g,!1)
B.aaO=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.aVZ=new A.a8(B.be,B.aaO,!1)
B.a4Y=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.aVH=new A.a8(B.c6,B.a4Y,!1)
B.a19=s([B.agI,B.aWt,B.aVP,B.aVZ,B.aVH],t.a)
B.aWW=new A.cy("story_04_flowers_in_mud",B.a19)
B.ah4=new A.b2("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.a2W=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.aUE=new A.a8(B.be,B.a2W,!1)
B.a0D=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.aVB=new A.a8(B.cc,B.a0D,!1)
B.a5t=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.aWC=new A.a8(B.be,B.a5t,!1)
B.acn=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.aUZ=new A.a8(B.c6,B.acn,!1)
B.a7S=s([B.ah4,B.aUE,B.aVB,B.aWC,B.aUZ],t.a)
B.aXv=new A.cy("story_05_old_oak",B.a7S)
B.ah0=new A.b2("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.a8R=s(["\u201eCo se to stalo?\u201c"],t.s)
B.aWk=new A.a8(B.be,B.a8R,!1)
B.a5j=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.aUX=new A.a8(B.c6,B.a5j,!1)
B.a33=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.aUV=new A.a8(B.be,B.a33,!1)
B.a5V=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.aVK=new A.a8(B.c6,B.a5V,!1)
B.agN=new A.b2("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.a5w=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.aVy=new A.a8(B.cc,B.a5w,!1)
B.ac4=s([B.ah0,B.aWk,B.aUX,B.aUV,B.aVK,B.agN,B.aVy],t.a)
B.aX0=new A.cy("story_06_waterfall_chest",B.ac4)
B.ahi=new A.b2("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.a48=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.aWE=new A.a8(B.cc,B.a48,!1)
B.ac0=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.aUY=new A.a8(B.c6,B.ac0,!1)
B.ahB=new A.b2("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.acc=s([B.ahi,B.aWE,B.aUY,B.ahB],t.a)
B.aXg=new A.cy("story_07_scroll",B.acc)
B.agy=new A.b2("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.aaD=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.aWu=new A.a8(B.be,B.aaD,!1)
B.a9m=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.aU_=new A.a8(B.cc,B.a9m,!1)
B.a3e=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.aU4=new A.a8(B.be,B.a3e,!1)
B.a6u=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.aUF=new A.a8(B.cc,B.a6u,!1)
B.a7k=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.aWh=new A.a8(B.c6,B.a7k,!1)
B.a7T=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.aTX=new A.a8(B.cc,B.a7T,!1)
B.a7O=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.aUH=new A.a8(B.be,B.a7O,!1)
B.a5u=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.aVo=new A.a8(B.cc,B.a5u,!1)
B.a2u=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.aUs=new A.a8(B.c6,B.a2u,!1)
B.a2b=s([B.agy,B.aWu,B.aU_,B.aU4,B.aUF,B.aWh,B.aTX,B.aUH,B.aVo,B.aUs],t.a)
B.aX6=new A.cy("story_08_ending_dialogue",B.a2b)
B.a7Z=s([B.aXl,B.aX3,B.aWZ,B.aWY,B.aX_,B.aWW,B.aXv,B.aX0,B.aXg,B.aX6],t.WD)
